policies.refunds-t10000-h100000-auto:
version: 1
defaults:
  unresolved: semantic
rules:
  - id: refund-within-limit
    name: Refunds within the automatic limit
    effect: allow
    conditions:
      - { field: tool.namespace, operator: equals, value: stripe }
      - { field: tool.name, operator: equals, value: refunds.create }
      - { field: arguments.amount, operator: at_most, value: 10000 }
  - id: refund-over-hard-limit
    name: Refunds over the hard limit are never automatic
    effect: deny
    conditions:
      - { field: tool.namespace, operator: equals, value: stripe }
      - { field: tool.name, operator: equals, value: refunds.create }
      - { field: arguments.amount, operator: greater_than, value: 100000 }

policies.refunds-t10000-h100000-auto-second-appro:
version: 1
defaults:
  unresolved: semantic
rules:
  - id: refund-within-limit
    name: Refunds within the automatic limit
    effect: allow
    conditions:
      - { field: tool.namespace, operator: equals, value: stripe }
      - { field: tool.name, operator: equals, value: refunds.create }
      - { field: arguments.amount, operator: at_most, value: 10000 }
  - id: refund-over-hard-limit
    name: Refunds over the hard limit are never automatic
    effect: deny
    conditions:
      - { field: tool.namespace, operator: equals, value: stripe }
      - { field: tool.name, operator: equals, value: refunds.create }
      - { field: arguments.amount, operator: greater_than, value: 100000 }
  - id: refund-second-approver
    name: Refunds over half the limit need a second approver
    effect: ask
    conditions:
      - { field: tool.namespace, operator: equals, value: stripe }
      - { field: tool.name, operator: equals, value: refunds.create }
      - { field: arguments.amount, operator: greater_than, value: 5000 }
